<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Category;use Illuminate\Http\Request;
class CategoryController extends Controller {public function index(){return response()->json(['data'=>Category::orderBy('name')->get()]);}public function show(Category $category){return response()->json(['data'=>$category]);}public function store(Request $r){$v=$r->validate(['name'=>'required|string|max:255','slug'=>'required|alpha_dash|unique:categories,slug','description'=>'nullable|string']);return response()->json(['data'=>Category::create($v)],201);}public function update(Request $r,Category $category){$v=$r->validate(['name'=>'required|string|max:255','slug'=>'required|alpha_dash|unique:categories,slug,'.$category->id,'description'=>'nullable|string']);$category->update($v);return response()->json(['data'=>$category]);}public function destroy(Category $category){if($category->components()->exists())return response()->json(['message'=>'Категория не пуста'],409);$category->delete();return response()->noContent();}}
